CREATE INDEX idx_exercise_image_exercise ON ExerciseImage(exerciseId)
CREATE INDEX idx_exercise_muscle_muscle ON ExerciseMuscle(muscleId)
CREATE INDEX idx_exercise_name ON Exercise(nameEs)
CREATE INDEX idx_food_name ON Food(name)
CREATE INDEX idx_foodlog_date ON FoodLogEntry(date)
CREATE INDEX idx_measurement_date ON BodyMeasurement(date)
CREATE INDEX idx_recipe_ingredient_recipe ON RecipeIngredient(recipeId)
CREATE INDEX idx_routine_day_routine ON RoutineDay(routineId)
CREATE INDEX idx_routine_exercise_day ON RoutineExercise(routineDayId)
CREATE INDEX idx_session_date ON WorkoutSession(date)
CREATE INDEX idx_setlog_exercise ON SetLog(exerciseId)
CREATE INDEX idx_setlog_session ON SetLog(sessionId)
CREATE TABLE BodyMeasurement (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, weightKg REAL NOT NULL, neckCm REAL, waistCm REAL, hipCm REAL, bodyFatPercent REAL, notes TEXT)
CREATE TABLE DietPlan (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, targetKcal REAL, targetProteinG REAL, targetCarbsG REAL, targetFatG REAL, isActive INTEGER NOT NULL DEFAULT 0)
CREATE TABLE DietPlanMeal (id INTEGER PRIMARY KEY AUTOINCREMENT, dietPlanId INTEGER NOT NULL REFERENCES DietPlan(id) ON DELETE CASCADE, mealType TEXT NOT NULL, foodId INTEGER REFERENCES Food(id), recipeId INTEGER REFERENCES Recipe(id), grams REAL, servings REAL, CHECK ((foodId IS NULL) != (recipeId IS NULL)))
CREATE TABLE Equipment (id INTEGER PRIMARY KEY, nameEs TEXT NOT NULL)
CREATE TABLE Exercise (id INTEGER PRIMARY KEY AUTOINCREMENT, wgerId INTEGER UNIQUE, nameEs TEXT NOT NULL, nameEn TEXT, descriptionEs TEXT, categoryId INTEGER, videoUrl TEXT, metValue REAL NOT NULL DEFAULT 3.5, exerciseType TEXT NOT NULL DEFAULT 'REPS', isCustom INTEGER NOT NULL DEFAULT 0)
CREATE TABLE ExerciseEquipment (exerciseId INTEGER NOT NULL REFERENCES Exercise(id) ON DELETE CASCADE, equipmentId INTEGER NOT NULL REFERENCES Equipment(id), PRIMARY KEY (exerciseId, equipmentId))
CREATE TABLE ExerciseImage (id INTEGER PRIMARY KEY AUTOINCREMENT, exerciseId INTEGER NOT NULL REFERENCES Exercise(id) ON DELETE CASCADE, url TEXT NOT NULL, isMain INTEGER NOT NULL DEFAULT 0)
CREATE TABLE ExerciseMuscle (exerciseId INTEGER NOT NULL REFERENCES Exercise(id) ON DELETE CASCADE, muscleId INTEGER NOT NULL REFERENCES Muscle(id), role TEXT NOT NULL, PRIMARY KEY (exerciseId, muscleId))
CREATE TABLE Food (id INTEGER PRIMARY KEY AUTOINCREMENT, offBarcode TEXT UNIQUE, name TEXT NOT NULL, brand TEXT, kcalPer100 REAL NOT NULL DEFAULT 0, proteinPer100 REAL NOT NULL DEFAULT 0, carbsPer100 REAL NOT NULL DEFAULT 0, fatPer100 REAL NOT NULL DEFAULT 0, fiberPer100 REAL, servingSizeG REAL, imageUrl TEXT, isCustom INTEGER NOT NULL DEFAULT 0, cachedAt TEXT)
CREATE TABLE FoodLogEntry (id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT NOT NULL, mealType TEXT NOT NULL, foodId INTEGER REFERENCES Food(id), recipeId INTEGER REFERENCES Recipe(id), grams REAL, servings REAL, loggedAt TEXT NOT NULL, CHECK ((foodId IS NULL) != (recipeId IS NULL)))
CREATE TABLE Muscle (id INTEGER PRIMARY KEY, nameEs TEXT NOT NULL, nameEn TEXT, isFront INTEGER NOT NULL DEFAULT 1, muscleGroupId INTEGER NOT NULL REFERENCES MuscleGroup(id))
CREATE TABLE MuscleGroup (id INTEGER PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL)
CREATE TABLE Recipe (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, servings INTEGER NOT NULL DEFAULT 1, notes TEXT)
CREATE TABLE RecipeIngredient (id INTEGER PRIMARY KEY AUTOINCREMENT, recipeId INTEGER NOT NULL REFERENCES Recipe(id) ON DELETE CASCADE, foodId INTEGER NOT NULL REFERENCES Food(id), grams REAL NOT NULL)
CREATE TABLE Routine (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, goal TEXT NOT NULL DEFAULT 'HIPERTROFIA', createdAt TEXT NOT NULL, isActive INTEGER NOT NULL DEFAULT 0, isGenerated INTEGER NOT NULL DEFAULT 0)
CREATE TABLE RoutineDay (id INTEGER PRIMARY KEY AUTOINCREMENT, routineId INTEGER NOT NULL REFERENCES Routine(id) ON DELETE CASCADE, dayIndex INTEGER NOT NULL, name TEXT NOT NULL, weekday INTEGER)
CREATE TABLE RoutineExercise (id INTEGER PRIMARY KEY AUTOINCREMENT, routineDayId INTEGER NOT NULL REFERENCES RoutineDay(id) ON DELETE CASCADE, exerciseId INTEGER NOT NULL REFERENCES Exercise(id), position INTEGER NOT NULL, targetSets INTEGER NOT NULL DEFAULT 3, targetRepsMin INTEGER, targetRepsMax INTEGER, targetTimeSeconds INTEGER, targetWeight REAL, restSeconds INTEGER NOT NULL DEFAULT 90, notes TEXT)
CREATE TABLE SetLog (id INTEGER PRIMARY KEY AUTOINCREMENT, sessionId INTEGER NOT NULL REFERENCES WorkoutSession(id) ON DELETE CASCADE, exerciseId INTEGER NOT NULL REFERENCES Exercise(id), setNumber INTEGER NOT NULL, weightKg REAL, reps INTEGER, timeSeconds INTEGER, isWarmup INTEGER NOT NULL DEFAULT 0, rpe REAL)
CREATE TABLE UserProfile (id INTEGER PRIMARY KEY CHECK (id = 1), name TEXT, sex TEXT NOT NULL DEFAULT 'M', birthDate TEXT, heightCm REAL, activityFactor REAL NOT NULL DEFAULT 1.375, goal TEXT, targetKcalOverride REAL)
CREATE TABLE WorkoutSession (id INTEGER PRIMARY KEY AUTOINCREMENT, routineId INTEGER, routineDayId INTEGER, date TEXT NOT NULL, startTime TEXT, durationMinutes INTEGER, kcalBurned REAL, notes TEXT, isCompleted INTEGER NOT NULL DEFAULT 0)